CREATE TABLE IF NOT EXISTS pitlane.monitors(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,project_id uuid NOT NULL,input jsonb NOT NULL,enabled boolean NOT NULL DEFAULT false,interval_seconds integer NOT NULL DEFAULT 86400 CHECK(interval_seconds>=3600),next_due timestamptz NOT NULL,expires_at timestamptz NOT NULL,unit_cap integer NOT NULL CHECK(unit_cap>0),used_units integer NOT NULL DEFAULT 0 CHECK(used_units>=0 AND used_units<=unit_cap),price_cap_cents bigint NOT NULL DEFAULT 400,cost_cap_micro bigint NOT NULL DEFAULT 1000000,policy_version text NOT NULL DEFAULT '1',paused_reason text,enabled_by uuid,FOREIGN KEY(project_id,tenant_id) REFERENCES pitlane.projects(id,tenant_id),UNIQUE(id,tenant_id,project_id));
CREATE TABLE IF NOT EXISTS pitlane.monitor_runs(monitor_id uuid,scheduled_for timestamptz,tenant_id uuid NOT NULL,project_id uuid NOT NULL,job_id uuid NOT NULL,PRIMARY KEY(monitor_id,scheduled_for),FOREIGN KEY(monitor_id,tenant_id,project_id) REFERENCES pitlane.monitors(id,tenant_id,project_id),FOREIGN KEY(job_id,tenant_id,project_id) REFERENCES pitlane.jobs(id,tenant_id,project_id));
CREATE TABLE IF NOT EXISTS pitlane.atlas_cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,project_id uuid NOT NULL,title text NOT NULL,state text NOT NULL DEFAULT 'proposed' CHECK(state IN('proposed','confirmed','withdrawn')),failure_version_id uuid NOT NULL,correction_version_id uuid,regression_artifact_id uuid,permission boolean NOT NULL DEFAULT false,expires_at timestamptz NOT NULL DEFAULT now()+interval '90 days',created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(failure_version_id,tenant_id,project_id) REFERENCES pitlane.receipt_versions(id,tenant_id,project_id),FOREIGN KEY(correction_version_id,tenant_id,project_id) REFERENCES pitlane.receipt_versions(id,tenant_id,project_id),FOREIGN KEY(regression_artifact_id,tenant_id,project_id) REFERENCES pitlane.artifacts(id,tenant_id,project_id));
CREATE TABLE IF NOT EXISTS pitlane.audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES pitlane.tenants,actor_id uuid,type text NOT NULL,subject_id uuid,occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS pitlane.workers(id text PRIMARY KEY,build text NOT NULL,heartbeat_at timestamptz NOT NULL DEFAULT now(),active integer NOT NULL DEFAULT 0 CHECK(active>=0),capabilities jsonb NOT NULL);
DO $$ DECLARE n text; BEGIN FOREACH n IN ARRAY ARRAY['monitors','monitor_runs','atlas_cases'] LOOP EXECUTE format('ALTER TABLE pitlane.%I ENABLE ROW LEVEL SECURITY',n);EXECUTE format('DROP POLICY IF EXISTS scoped_read ON pitlane.%I',n);EXECUTE format('CREATE POLICY scoped_read ON pitlane.%I FOR SELECT USING(pitlane.can_project(tenant_id,project_id))',n);EXECUTE format('GRANT SELECT ON pitlane.%I TO pitlane_web',n);END LOOP; END $$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA pitlane FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pitlane.actor_id(),pitlane.actor_tenant(),pitlane.can_tenant(uuid),pitlane.can_project(uuid,uuid,boolean),pitlane.can_billing(uuid) TO pitlane_web;
